import os
import shutil
from pyspark.sql import functions as F

STORE = "/tmp/event_store/events"


def run_order(deps):
    order = []
    while len(order) < len(deps):
        ready = [t for t in deps if t not in order and all(d in order for d in deps[t])]
        if not ready:
            raise ValueError("these tasks wait on each other: " + ", ".join(t for t in deps if t not in order))
        order += ready
    return order


def make_tasks(shipments, tonight):
    def new_events():
        # Tonight's events, one row per event, without the ones already stored.
        return tonight.select([c for c in tonight.columns if c != "load_date"]).distinct()

    def all_events(new_events):
        new_events.write.mode("append").parquet(STORE)
        return spark.read.parquet(STORE)

    def delivered(all_events):
        ids = [r.shipment_id for r in shipments.select("shipment_id").collect()]
        known = F.coalesce(F.col("shipment_id").isin(ids), F.lit(False))
        return all_events.filter(known & (F.col("event_type") == "delivered"))

    def in_flight(delivered):
        done = [r.shipment_id for r in delivered.select("shipment_id").collect()]
        return shipments.filter(~F.col("shipment_id").isin(done))

    return {
        "in_flight": (in_flight, ["delivered"]),
        "delivered": (delivered, ["all_events"]),
        "all_events": (all_events, ["new_events"]),
        "new_events": (new_events, []),
    }


